# Let me analyze which input row's value goes to which output column for each output column

# For each output column c, find which input rows r have input[r][c] non-zero
# and see if output[r][c] = input[r][c] (identity) or something else

print("Per-column analysis:")
for c in range(17):
    input_vals = []
    for r in range(17):
        in_val = input_demo[r][c]
        out_val = output_demo[r][c]
        if in_val != 0:
            input_vals.append((r, in_val, out_val))

    # Check if output at this column copies from input
    if any(v[1] == v[2] for v in input_vals):
        match_row = [v[0] for v in input_vals if v[1] == v[2]]
        print(f"Col {c}: matches at rows {match_row}, input values: {[v[1] for v in input_vals]}, output: {[v[2] for v in input_vals]}")

# Now let's see the overall mapping - which input (r,c) values end up where in output
print("\nAll input->output cell mappings:")
same_cells = 0
changed_cells = 0
for r in range(17):
    for c in range(17):
        if input_demo[r][c] != 0:
            if input_demo[r][c] == output_demo[r][c]:
                same_cells += 1
            else:
                changed_cells += 1
                print(f"  {r},{c}: {input_demo[r][c]} -> {output_demo[r][c]}")

print(f"\nCells that stayed same: {same_cells}")
print(f"Cells that changed: {changed_cells}")

# Look at the rows that have changed their values
# Specifically, which input row's value got moved to which output column
print("\nAnalyzing where values moved horizontally:")
for r in range(17):
    input_row = input_demo[r]
    output_row = output_demo[r]
    for c in range(17):
        if input_row[c] != 0 and output_row[c] != input_row[c]:
            print(f"Row {r}: {input_row[c]} at col {c} -> output[{r}][{c}]={output_row[c]}")

